Author: hvn_jack <hvn_jack@humax-networks.com>
Date:   Fri Mar 6 10:22:29 2026 +0000

    [ARHT-89] Fix kernel panic issue on dnstrap module

    Change-Id: I0b23ee9c40650f6010cf646f05808295efbd58c4

diff --git a/airoha_feeds/target/linux/airoha/patches/911_fix_dns_trap_crash.patch b/airoha_feeds/target/linux/airoha/patches/911_fix_dns_trap_crash.patch
new file mode 100755
index 00000000000..e1fc2e672c2
--- /dev/null
+++ b/airoha_feeds/target/linux/airoha/patches/911_fix_dns_trap_crash.patch
@@ -0,0 +1,33 @@
+Index: linux-5.4.55/net/bridge/dnstrap.c
+===================================================================
+--- linux-5.4.55.orig/net/bridge/dnstrap.c
++++ linux-5.4.55/net/bridge/dnstrap.c
+@@ -151,6 +151,7 @@ int br_dns_packet_recap(struct sk_buff *
+ int br_dns_packet_recap(struct sk_buff *skb,short type)
+ #endif
+ {
++    struct ethhdr *eh  = NULL;
+     struct iphdr *iph = NULL;
+     struct udphdr tmp_udphdr, *udph = NULL;
+     dnsheader_t *dns_pkt = NULL;
+@@ -203,9 +204,17 @@ int br_dns_packet_recap(struct sk_buff *
+     skb_put(skb,extend_len);
+ 
+ #if 1
+-    // [Jack] Fix received packet on xxx with own address as source address
+-    memcpy(eth_hdr(skb)->h_dest, eth_hdr(skb)->h_source, ETH_ALEN);
+-    memcpy(eth_hdr(skb)->h_source, mac_answer, ETH_ALEN);
++    eh  = eth_hdr(skb);
++    // Some packets may have no eth header (eg: ppp, ...) so we need to check the length before swap mac address, otherwise it may cause kernel panic.
++    if ((dns_ver == DNS_V4 && ((unsigned char *)iph - (unsigned char *)eh >= ETH_HLEN))
++#ifdef CONFIG_IPV6
++    || (dns_ver == DNS_V6 && ((unsigned char *)ipv6h - (unsigned char *)eh >= ETH_HLEN))
++#endif
++    ) {
++        // [Jack] Fix received packet on xxx with own address as source address
++        memcpy(eth_hdr(skb)->h_dest, eth_hdr(skb)->h_source, ETH_ALEN);
++        memcpy(eth_hdr(skb)->h_source, mac_answer, ETH_ALEN);
++    }
+ #else
+     /* swap mac address */
+     memcpy(mac, eth_hdr(skb)->h_dest, ETH_ALEN);

