Date:   Tue Mar 10 04:21:09 2026 +0000

    [HP2236BVA-134] Update ONT software version.

    Change-Id: Ifc33996b492d1d64760f6e31f3966bdb8f230d4b

diff --git a/tclinux_phoenix/apps/xpon_app/ponmgr_cfg/ponmgr_cfg.c b/tclinux_phoenix/apps/xpon_app/ponmgr_cfg/ponmgr_cfg.c
index 6941197ee08..e95c5d6784e 100755
--- a/tclinux_phoenix/apps/xpon_app/ponmgr_cfg/ponmgr_cfg.c
+++ b/tclinux_phoenix/apps/xpon_app/ponmgr_cfg/ponmgr_cfg.c
@@ -83,6 +83,10 @@ typedef enum {
 *                  M A C R O S
 *************************************************************************
 */    
+#define UCI_OPTION_SW_VERSION		"system.@devinfo[0].software_version"
+#define UCI_CONFIG_GPON			"gpon"
+#define UCI_OPTION_GPON_SW0_VERSION	"gpon.SoftImage0.Version"
+#define UCI_OPTION_GPON_SW1_VERSION	"gpon.SoftImage1.Version"

 /************************************************************************
 *                  D A T A     T Y P E S
@@ -508,6 +512,36 @@ int insmodComboPonKo(void){
 	return 0;
 }

+static void update_xpon_sw_version(void)
+{
+	char buffer[16] = {0};
+	char cmd[128] = {0};
+	uint8_t bootflag = 0;
+
+	omci_lib_uci_get(UCI_OPTION_SW_VERSION, buffer, sizeof(buffer));
+	if (strlen(buffer) == 0) {
+		return;
+	}
+
+	blapi_pon_get_boot_flag(&bootflag);
+
+	if (bootflag == 0) {
+		snprintf(cmd, sizeof(cmd), "uci -q set %s=%s", UCI_OPTION_GPON_SW0_VERSION, buffer);
+	} else {
+		snprintf(cmd, sizeof(cmd), "uci -q set %s=%s", UCI_OPTION_GPON_SW1_VERSION, buffer);
+	}
+	system(cmd);
+
+	snprintf(cmd, sizeof(cmd), "uci -q commit %s", UCI_CONFIG_GPON);
+	system(cmd);
+
+	if (oam_lib_set_software_version((unsigned char *)buffer) == -1) {
+		printf("oam_lib_set_software_version fail\n");
+	}
+
+	return;
+}
+
 int main(int argc, char **argv)
 {
 	int xponMode =0;
@@ -528,6 +562,7 @@ int main(int argc, char **argv)
 	pon_config_onu_portmap();
 	load_xpon_config_for_shareMem();

+	update_xpon_sw_version();
 	omci_lib_get_onu_emergency(&emergencyState);
 	gponmgr_lib_set_emergency(emergencyState);

