+static inline void hmx_fill_ascii_payload(char *pos, char *end)
+{
+    static const char pattern[] =
+        "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
+        "!@#$%^&*()_+-={}[]|:;<>,.?/~`"
+        "\n";
+
+    size_t cap = (size_t)(end - pos);
+    size_t pat_len = sizeof(pattern) - 1; // exclude '\0'
+    size_t off = 0;
+
+    if (!pos || !end || end <= pos || cap == 0)
+        return;
+
+    while (off < cap) {
+        size_t chunk = pat_len;
+        if (chunk > (cap - off))
+            chunk = cap - off;
+
+        memcpy(pos + off, pattern, chunk);
+        off += chunk;
+    }
+}
