+        }
+
+        pos = (char *)arg;
+        cap = HMX_MTK_NL80211_VENDOR_SUBCMD_VENDOR_SHOW_BUFFER_SIZE;
+        end = pos + cap;
+
+
+        hmx_fill_ascii_payload(pos, end - 1); // 마지막 1바이트 남김
+        pos[cap - 1] = '\0';

+        MTWF_PRINT("BUFTEST filled: cap=%zu, head=[%c%c%c%c], tail=[%c%c%c%c]\n",
+                   cap,
+                   pos[0], pos[1], pos[2], pos[3],
+                   pos[cap-5], pos[cap-4], pos[cap-3], pos[cap-2]);
+
+        return TRUE;
+
+}
