+			LastTxRate.field.ShortGI = rTxStatResult.rEntryTxRate.ShortGI ? 1 : 0;
+			LastTxRate.field.STBC = rTxStatResult.rEntryTxRate.STBC;
+			if (LastTxRate.field.MODE == MODE_VHT)
