+				LastTxRate.field.MCS = rTxStatResult.rEntryTxRate.MCS;
+			lastTxRate = (UINT32)(LastTxRate.word);
+			LastRxRate.word = (USHORT)(pEntry->LastRxRate);
+			RawData = lastTxRate;
+			bw = (RawData >> 7) & 0x3;
+			stbc = ((RawData >> 10) & 0x1);
+			if (phy_mode_r == MODE_OFDM) {
