+static void hni_switch_op_mode(void)
+{
+	FILE *fp = NULL;
+	char buf[16] = {0};
+
+	/* Execute uci get via popen */
+	fp = popen("/sbin/uci get clay.opermode.mode 2>/dev/null", "r");
+	if (!fp)
+		return;
+
+	fgets(buf, sizeof(buf), fp);
+	pclose(fp);
+
+	buf[strcspn(buf, "\r\n")] = '\0';
+	if (strcmp(buf, "auto") != 0)
+		return;
+
+	notice(DEBUG_CAT_BH_RECONF,"Agent backhaul is ready, change Auto Mode to AP and then reboot \n");
+	system("/sbin/uci set clay.opermode.mode=ap");
+	system("/sbin/uci commit clay");
+	system("/etc/init.d/opermode reload");
+}
